import{_ as e,o as a,c as o,ag as i}from"./chunks/framework.B9unkguw.js";const g=JSON.parse('{"title":"Actuators / Motors (PX4)","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/setup_view/px4/actuators.md","filePath":"en/qgc-user-guide/setup_view/px4/actuators.md"}'),r={name:"en/qgc-user-guide/setup_view/px4/actuators.md"};function n(s,t,d,c,l,u){return a(),o("div",null,t[0]||(t[0]=[i('<h1 id="actuators-motors-px4" tabindex="-1">Actuators / Motors (PX4) <a class="header-anchor" href="#actuators-motors-px4" aria-label="Permalink to &quot;Actuators / Motors (PX4)&quot;">​</a></h1><p>The Actuators page provides a unified interface for configuring motor and servo outputs on PX4 vehicles (PX4 v1.13+).</p><h2 id="geometry-mixer" tabindex="-1">Geometry / Mixer <a class="header-anchor" href="#geometry-mixer" aria-label="Permalink to &quot;Geometry / Mixer&quot;">​</a></h2><p>The top section displays the vehicle&#39;s actuator geometry, dynamically generated from the mixer configuration. For multirotor vehicles, an SVG diagram shows motor positions — you can click individual motors to select them. Each actuator channel has configurable parameters such as position offsets and tilt angles.</p><h2 id="actuator-outputs" tabindex="-1">Actuator Outputs <a class="header-anchor" href="#actuator-outputs" aria-label="Permalink to &quot;Actuator Outputs&quot;">​</a></h2><p>The right panel shows all output channels with:</p><ul><li><strong>Function</strong> — assign each output to a motor, servo, or other function</li><li><strong>Min / Max</strong> — PWM or DShot output range limits</li><li><strong>Failsafe</strong> — output value when failsafe is triggered</li><li><strong>Disarmed</strong> — output value when the vehicle is disarmed</li></ul><h2 id="actuator-testing" tabindex="-1">Actuator Testing <a class="header-anchor" href="#actuator-testing" aria-label="Permalink to &quot;Actuator Testing&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Remove all propellers before testing actuators.</p></div><p>With the safety switch toggled, individual actuator sliders appear for testing each channel. An optional <strong>All Motors</strong> slider allows spinning all motors simultaneously at low throttle for verification.</p><h2 id="actuator-actions" tabindex="-1">Actuator Actions <a class="header-anchor" href="#actuator-actions" aria-label="Permalink to &quot;Actuator Actions&quot;">​</a></h2><p>Dynamic action buttons (e.g., beep, identify, 3D mode) are shown based on the vehicle&#39;s actuator configuration. The <strong>motor identification</strong> feature spins motors one at a time to verify correct wiring and rotation direction.</p><h2 id="troubleshooting-a-missing-actuators-page" tabindex="-1">Troubleshooting a Missing Actuators Page <a class="header-anchor" href="#troubleshooting-a-missing-actuators-page" aria-label="Permalink to &quot;Troubleshooting a Missing Actuators Page&quot;">​</a></h2><p>The Actuators page is shown when QGroundControl receives and initializes the vehicle&#39;s <code>COMP_METADATA_TYPE_ACTUATORS</code> component metadata. The firmware version alone does not determine whether the page is available. If the metadata is unavailable, cannot be initialized, or its top-level <code>show-ui-if</code> condition evaluates to false, QGroundControl uses the legacy Motors page instead.</p><h3 id="capture-diagnostic-logs" tabindex="-1">Capture Diagnostic Logs <a class="header-anchor" href="#capture-diagnostic-logs" aria-label="Permalink to &quot;Capture Diagnostic Logs&quot;">​</a></h3><ol><li>Open <strong>Application Settings &gt; App Log Viewer</strong>.</li><li>Click <strong>Categories</strong> and enable these categories: <ul><li><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></li><li><code>Vehicle.Actuators.Common</code></li><li><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></li><li><code>Vehicle.FTPManager</code></li></ul></li><li>Connect the vehicle. If it is already connected, disconnect and reconnect it so that QGroundControl requests the component metadata again.</li><li>Open <strong>Vehicle Setup</strong> and check whether <strong>Actuators</strong> or <strong>Motors</strong> is available.</li><li>Return to <strong>App Log Viewer</strong> and click <strong>Save</strong>. Keep the saved app log unchanged when attaching it to a support request.</li></ol><p>The metadata URI can use MAVLink FTP (<code>mavlinkftp://</code>) or HTTP. QGroundControl tries the primary URI first and then the fallback URI advertised by the vehicle.</p><h3 id="read-the-diagnostic-messages" tabindex="-1">Read the Diagnostic Messages <a class="header-anchor" href="#read-the-diagnostic-messages" aria-label="Permalink to &quot;Read the Diagnostic Messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Log category</th><th>Message or pattern</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></td><td><code>Vehicle did not provide actuators metadata via component information</code></td><td>No actuator metadata was received from the vehicle.</td></tr><tr><td><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></td><td><code>Actuators initialization failed</code></td><td>Metadata was received but could not be parsed or initialized.</td></tr><tr><td><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></td><td><code>Condition &#39;show-ui-if&#39; evaluated to false</code></td><td>The vehicle&#39;s metadata indicated the page should not be shown. This can be intentional for your configuration, or a firmware/metadata mismatch. Attach the saved log to a support request.</td></tr><tr><td><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></td><td><code>primary failed, requesting metadata (fallback) from ...</code></td><td>The primary metadata URI failed and QGroundControl is trying the fallback URI.</td></tr><tr><td><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></td><td><code>FTP download failed</code> or <code>HTTP download failed</code></td><td>The selected transport could not download the metadata. An HTTP status such as <code>404</code> identifies a missing or incorrect URL.</td></tr><tr><td><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></td><td><code>failed to load metadata (primary and fallback)</code></td><td>Both metadata URIs failed, so the Actuators page cannot be initialized.</td></tr><tr><td><code>Vehicle.FTPManager</code></td><td><code>Download fromCompId</code>, <code>Nak - ...</code>, or timeout messages</td><td>Details of the MAVLink FTP request and any vehicle-side error.</td></tr></tbody></table><h3 id="include-this-information-in-a-support-request" tabindex="-1">Include This Information in a Support Request <a class="header-anchor" href="#include-this-information-in-a-support-request" aria-label="Permalink to &quot;Include This Information in a Support Request&quot;">​</a></h3><p>Include the QGroundControl version and build, PX4 firmware version, vehicle type, connection type, whether the legacy Motors page appears, and the saved app log. If the log contains a fallback or download error, include the full line with the URI and error text. Also mention whether reconnecting the vehicle changes the result.</p>',21)]))}const p=e(r,[["render",n]]);export{g as __pageData,p as default};
